# -*- coding: utf-8 -*-
# «ما لا يسع المسلم جهله»: دروس قصيرة جداً تصل بالإشعار كل يوم. كل درس: عنوان، ونص قصير بسيط، ودليله، وسؤال تثبيت.
# اقتصرنا على ما اتفق عليه أهل العلم أو قول الجمهور، وما فيه خلاف مشهور يُنبَّه عليه.
from dawah_src import Q, H, B
UNITS = [('aqida', '🤍', 'العقيدة'), ('tahara', '💧', 'الطهارة'), ('salah', '🕌', 'الصلاة'), ('siyam', '🌙', 'الصيام'), ('zakah', '💰', 'الزكاة'), ('hajj', '🕋', 'الحج والعمرة'), ('haram', '⛔', 'الحلال والحرام'), ('akhlaq', '🌿', 'الأخلاق والآداب')]
W = []
def w(u, t, b, ev, q): W.append(dict(u=u, t=t, b=b, ev=ev, q=q))

# ===== العقيدة =====
w('aqida', 'لماذا خُلقنا؟', 'خلقنا الله لغاية واحدة: أن نعبده وحده. والعبادة كل ما يحبه الله من قول أو عمل: الصلاة، والصدق، وبر الوالدين، وحتى النوم بنية التقوّي على الطاعة.', [Q(51, 56)], ('الغاية من خلق الإنسان:', ['جمع المال', 'عبادة الله', 'الراحة'], 1))
w('aqida', 'معنى «لا إله إلا الله»', 'معناها: لا معبود بحق إلا الله. فيها نفي (لا إله) وإثبات (إلا الله): ننفي العبادة عن كل ما سوى الله، ونثبتها لله وحده.', [Q(47, 19), H('hadith-muslim', 'من مات وهو يعلم أنه لا إله إلا الله', '«من مات وهو يعلم أنه لا إله إلا الله دخل الجنة»', 'رواه مسلم')], ('معنى «لا إله إلا الله»:', ['لا خالق إلا الله فقط', 'لا معبود بحق إلا الله', 'لا رازق إلا الله فقط'], 1))
w('aqida', 'أركان الإسلام الخمسة', 'الشهادتان، وإقامة الصلاة، وإيتاء الزكاة، وصوم رمضان، وحج البيت لمن استطاع. هذه هي الأعمدة التي يقوم عليها بناء الإسلام.', [H('hadith-bukhari', 'بني الإسلام على خمس', '«بُني الإسلام على خمس: شهادة أن لا إله إلا الله وأن محمداً رسول الله، وإقام الصلاة، وإيتاء الزكاة، والحج، وصوم رمضان»', 'متفق عليه')], ('كم أركان الإسلام؟', ['ثلاثة', 'خمسة', 'ستة'], 1))
w('aqida', 'أركان الإيمان الستة', 'أن تؤمن بالله، وملائكته، وكتبه، ورسله، واليوم الآخر، وبالقدر خيره وشره. من أنكر واحداً منها لم يكن مؤمناً.', [H('hadith-muslim', 'أن تؤمن بالله وملائكته وكتبه ورسله', '«أن تؤمن بالله، وملائكته، وكتبه، ورسله، واليوم الآخر، وتؤمن بالقدر خيره وشره»', 'رواه مسلم (حديث جبريل)')], ('كم أركان الإيمان؟', ['خمسة', 'ستة', 'سبعة'], 1))
w('aqida', 'الإحسان: أعلى الدرجات', 'الإحسان: أن تعبد الله كأنك تراه، فإن لم تكن تراه فإنه يراك. استحضر هذا في صلاتك ووحدتك، فهو يغيّر كل شيء.', [H('hadith-muslim', 'أن تعبد الله كأنك تراه', '«أن تعبد الله كأنك تراه، فإن لم تكن تراه فإنه يراك»', 'رواه مسلم')], ('مراتب الدين ثلاث، أعلاها:', ['الإسلام', 'الإيمان', 'الإحسان'], 2))
w('aqida', 'التوحيد ثلاثة أنواع', 'توحيد الربوبية: الله وحده الخالق الرازق المدبّر. وتوحيد الألوهية: إفراد الله بالعبادة. وتوحيد الأسماء والصفات: إثبات ما أثبته لنفسه بلا تشبيه ولا تعطيل.', [Q(1, 2, 5), Q(42, 11)], ('إفراد الله بالعبادة يسمى:', ['توحيد الربوبية', 'توحيد الألوهية', 'توحيد الأسماء'], 1))
w('aqida', 'أعظم ذنب: الشرك', 'الشرك أن تجعل لله شريكاً في العبادة: كدعاء غيره، أو الذبح أو النذر لغيره. وهو الذنب الذي لا يغفره الله لمن مات عليه.', [Q(4, 48), H('hadith-bukhari', 'أي الذنب أعظم', 'سُئل ﷺ: أي الذنب أعظم؟ قال: «أن تجعل لله نداً وهو خلقك»', 'متفق عليه')], ('الذنب الذي لا يُغفر لمن مات عليه:', ['الكذب', 'الشرك', 'الغيبة'], 1))
w('aqida', 'الدعاء عبادة لا تُصرف إلا لله', 'الدعاء من أعظم العبادات، فلا تدعُ إلا الله: لا ميتاً ولا ولياً ولا قبراً. والله قريب يسمعك بلا واسطة.', [Q(40, 60), Q(2, 186)], ('من ندعو عند الحاجة؟', ['الله وحده', 'الأولياء', 'أصحاب القبور'], 0))
w('aqida', 'الإيمان بالملائكة', 'الملائكة عباد مكرمون خُلقوا من نور، لا يعصون الله. منهم جبريل الموكّل بالوحي، وميكائيل بالمطر، وإسرافيل بالنفخ في الصور، ومعك ملكان يكتبان عملك.', [Q(66, 6), Q(50, 17, 18)], ('الملائكة خُلقوا من:', ['نار', 'نور', 'طين'], 1))
w('aqida', 'الإيمان بالكتب', 'أنزل الله كتباً على رسله: التوراة على موسى، والإنجيل على عيسى، والزبور على داود، والقرآن على محمد ﷺ، وهو آخرها والمهيمن عليها والمحفوظ من التحريف.', [Q(15, 9), Q(5, 48)], ('الكتاب الذي تكفّل الله بحفظه:', ['التوراة', 'الإنجيل', 'القرآن'], 2))
w('aqida', 'الإيمان بالرسل', 'أرسل الله رسلاً مبشّرين ومنذرين، أولهم نوح وآخرهم محمد ﷺ خاتم النبيين، فلا نبي بعده. وأولو العزم خمسة: نوح وإبراهيم وموسى وعيسى ومحمد.', [Q(33, 40), Q(4, 165)], ('خاتم الأنبياء:', ['عيسى', 'محمد ﷺ', 'موسى'], 1))
w('aqida', 'الإيمان باليوم الآخر', 'يشمل: سؤال القبر ونعيمه وعذابه، والبعث، والحساب، والميزان، والصراط، والحوض، والجنة والنار. وكل إنسان سيقف بين يدي الله فيسأله.', [Q(99, 7, 8)], ('أول منازل الآخرة:', ['الصراط', 'القبر', 'الميزان'], 1))
w('aqida', 'الإيمان بالقدر', 'أن تؤمن أن الله علم كل شيء، وكتبه، وشاءه، وخلقه. وللإنسان مشيئة واختيار يحاسب عليهما. فاعمل وخذ بالأسباب، وارضَ بما قدّر الله.', [Q(54, 49), H('hadith-muslim', 'احرص على ما ينفعك', '«احرص على ما ينفعك، واستعن بالله ولا تعجز»', 'رواه مسلم')], ('هل للإنسان اختيار؟', ['لا، هو مجبور', 'نعم، وله مشيئة يحاسب عليها'], 1))
w('aqida', 'محبة النبي ﷺ واتباعه', 'شهادة أن محمداً رسول الله تعني: تصديقه فيما أخبر، وطاعته فيما أمر، واجتناب ما نهى عنه، وألا يُعبد الله إلا بما شرع.', [Q(3, 31), H('hadith-bukhari', 'لا يؤمن أحدكم حتى أكون أحب إليه', '«لا يؤمن أحدكم حتى أكون أحب إليه من والده وولده والناس أجمعين»', 'متفق عليه')], ('علامة محبة النبي ﷺ الصادقة:', ['الاحتفال فقط', 'اتباعه وطاعته'], 1))
w('aqida', 'البدعة', 'البدعة: عبادة لم يشرعها الله ولا رسوله. والدين كامل لا يحتاج زيادة، فكل عبادة تحتاج دليلاً.', [Q(5, 3), H('hadith-bukhari', 'ما ليس فيه فهو رد', '«من أحدث في أمرنا هذا ما ليس فيه فهو ردّ»', 'متفق عليه')], ('العبادة يُشترط فيها:', ['أن يستحسنها الناس', 'أن يكون عليها دليل'], 1))
w('aqida', 'السحر والكهانة', 'إتيان السحرة والعرافين وتصديقهم في الغيب محرّم وخطير على الإيمان، فلا يعلم الغيب إلا الله. والعلاج بالرقية الشرعية والأذكار.', [Q(27, 65), H('hadith-muslim', 'من أتى عرافا فسأله عن شيء', '«من أتى عرّافاً فسأله عن شيء لم تُقبل له صلاة أربعين ليلة»', 'رواه مسلم')], ('من يعلم الغيب؟', ['الكاهن', 'الله وحده', 'المنجم'], 1))

# ===== الطهارة =====
w('tahara', 'الطهارة مفتاح الصلاة', 'لا تصح الصلاة إلا بطهارة: طهارة البدن والثوب والمكان من النجاسة، والطهارة من الحدث بالوضوء أو الغسل.', [H('hadith-muslim', 'لا تقبل صلاة بغير طهور', '«لا تُقبل صلاة بغير طهور»', 'رواه مسلم'), Q(5, 6)], ('هل تصح الصلاة بلا وضوء لمن قدر عليه؟', ['نعم', 'لا'], 1))
w('tahara', 'فرائض الوضوء', 'غسل الوجه (ومنه المضمضة والاستنشاق عند جمع من العلماء)، وغسل اليدين إلى المرفقين، ومسح الرأس، وغسل الرجلين إلى الكعبين. ويجب الترتيب والموالاة عند جمهور العلماء.', [Q(5, 6)], ('حدّ غسل اليدين في الوضوء:', ['إلى الرسغين', 'إلى المرفقين', 'إلى الكتفين'], 1))
w('tahara', 'صفة الوضوء الكاملة', 'تنوي، وتسمّي، وتغسل كفيك ثلاثاً، ثم تتمضمض وتستنشق ثلاثاً، وتغسل وجهك ثلاثاً، ويديك إلى المرفقين ثلاثاً، وتمسح رأسك مرة مع الأذنين، وتغسل رجليك إلى الكعبين ثلاثاً.', [H('hadith-bukhari', 'من توضأ نحو وضوئي هذا', 'وصف عثمان رضي الله عنه وضوء النبي ﷺ ثلاثاً ثلاثاً، ثم قال: «من توضأ نحو وضوئي هذا ثم صلى ركعتين... غُفر له ما تقدم من ذنبه»', 'متفق عليه')], ('مسح الرأس يكون:', ['ثلاث مرات', 'مرة واحدة'], 1))
w('tahara', 'نواقض الوضوء', 'ما خرج من السبيلين (بول، غائط، ريح)، والنوم المستغرق، وزوال العقل. وفي مس الذكر وأكل لحم الإبل خلاف بين العلماء، والأحوط الوضوء منهما.', [H('hadith-bukhari', 'لا يقبل الله صلاة أحدكم إذا أحدث حتى يتوضأ', '«لا يقبل الله صلاة أحدكم إذا أحدث حتى يتوضأ»', 'متفق عليه')], ('خروج الريح:', ['لا ينقض الوضوء', 'ينقض الوضوء'], 1))
w('tahara', 'الشك في الوضوء', 'إذا توضأت ثم شككت هل خرج منك شيء؟ فأنت على وضوئك؛ لأن اليقين لا يزول بالشك. ولا تخرج من الصلاة حتى تسمع صوتاً أو تجد ريحاً.', [H('hadith-bukhari', 'لا ينصرف حتى يسمع صوتا', '«لا ينصرف حتى يسمع صوتاً أو يجد ريحاً»', 'متفق عليه')], ('توضأت ثم شككت في الحدث:', ['تعيد الوضوء', 'أنت على وضوئك'], 1))
w('tahara', 'الغسل وموجباته', 'يجب الغسل من الجنابة، والحيض والنفاس بعد انقطاعهما، والموت. وصفته المجزئة: النية وتعميم البدن بالماء مع المضمضة والاستنشاق عند جمع من العلماء.', [Q(5, 6)], ('من موجبات الغسل:', ['النوم', 'الجنابة', 'الأكل'], 1))
w('tahara', 'التيمم', 'إذا عُدم الماء أو تضرّر الإنسان باستعماله تيمّم: ينوي، ويضرب التراب بكفيه ضربة واحدة، ثم يمسح وجهه وكفيه.', [Q(5, 6), H('hadith-bukhari', 'إنما كان يكفيك', '«إنما كان يكفيك أن تقول بيديك هكذا» ثم ضرب بيديه الأرض ضربة واحدة، ثم مسح بهما وجهه وكفيه', 'متفق عليه (حديث عمار)')], ('التيمم يكون عند:', ['البرد الخفيف', 'عدم الماء أو الضرر باستعماله'], 1))
w('tahara', 'المسح على الخفين والجوارب', 'من لبس خفين أو جوربين على طهارة جاز له المسح عليهما بدل غسل القدمين: يوماً وليلة للمقيم، وثلاثة أيام بلياليها للمسافر.', [H('hadith-muslim', 'ثلاثة أيام ولياليهن للمسافر', 'جعل رسول الله ﷺ «ثلاثة أيام ولياليهن للمسافر، ويوماً وليلة للمقيم»', 'رواه مسلم')], ('مدة المسح للمقيم:', ['ثلاثة أيام', 'يوم وليلة'], 1))
w('tahara', 'الاستنجاء وعذاب القبر', 'التنزّه من البول واجب، ومن أسباب عذاب القبر عدم الاستتار منه. فاستنجِ بالماء أو بالحجارة ونحوها حتى يطهر المحل.', [H('hadith-bukhari', 'كان لا يستتر من البول', 'مرّ ﷺ بقبرين فقال: «إنهما ليعذبان... أما أحدهما فكان لا يستتر من البول»', 'متفق عليه')], ('عدم التنزه من البول:', ['أمر هيّن', 'من أسباب عذاب القبر'], 1))

# ===== الصلاة =====
w('salah', 'منزلة الصلاة', 'الصلاة عمود الدين، وأول ما يحاسب عليه العبد يوم القيامة، وهي الفارق بين المسلم والكافر. لا تسقط عن المكلف ما دام عقله معه.', [H('hadith-muslim', 'بين الرجل وبين الشرك والكفر ترك الصلاة', '«بين الرجل وبين الشرك والكفر ترك الصلاة»', 'رواه مسلم')], ('أول ما يحاسب عليه العبد:', ['الصيام', 'الصلاة', 'الزكاة'], 1))
w('salah', 'أوقات الصلوات الخمس', 'الفجر: من طلوع الفجر الصادق إلى طلوع الشمس. والظهر: من الزوال إلى أن يصير ظل الشيء مثله. ثم العصر إلى اصفرار الشمس (ووقت الضرورة إلى الغروب). والمغرب: من الغروب إلى مغيب الشفق. والعشاء: إلى نصف الليل.', [Q(4, 103), H('hadith-muslim', 'وقت الظهر إذا زالت الشمس', '«وقت الظهر إذا زالت الشمس... ووقت العصر ما لم تصفرّ الشمس... ووقت صلاة العشاء إلى نصف الليل»', 'رواه مسلم')], ('آخر وقت الفجر:', ['الظهر', 'طلوع الشمس', 'الضحى'], 1))
w('salah', 'شروط الصلاة', 'الإسلام، والعقل، والتمييز، ودخول الوقت، والطهارة من الحدث والنجس، وستر العورة، واستقبال القبلة، والنية.', [Q(2, 144)], ('من شروط الصلاة:', ['استقبال القبلة', 'رفع الصوت', 'الجماعة'], 0))
w('salah', 'أركان الصلاة', 'لا تصح الصلاة بتركها: القيام للقادر، وتكبيرة الإحرام، وقراءة الفاتحة، والركوع، والرفع منه، والسجود، والجلوس بين السجدتين، والتشهد الأخير، والسلام، والطمأنينة في كل ذلك، والترتيب.', [H('hadith-bukhari', 'لا صلاة لمن لم يقرأ بفاتحة الكتاب', '«لا صلاة لمن لم يقرأ بفاتحة الكتاب»', 'متفق عليه')], ('قراءة الفاتحة في الصلاة:', ['سنة', 'ركن'], 1))
w('salah', 'الطمأنينة', 'الطمأنينة ركن: أن تستقر في الركوع والسجود حتى يرجع كل عظم إلى مكانه. والسرعة التي تنقر فيها الصلاة تبطلها.', [H('hadith-bukhari', 'ارجع فصل فإنك لم تصل', 'قال ﷺ للمسيء صلاته: «ارجع فصلِّ فإنك لم تصلِّ» ثم علّمه: «ثم اركع حتى تطمئن راكعاً...»', 'متفق عليه')], ('الطمأنينة في الركوع:', ['مستحبة', 'ركن لا تصح الصلاة بدونه'], 1))
w('salah', 'صلاة الجماعة للرجال', 'صلاة الجماعة أفضل من صلاة الفرد بسبع وعشرين درجة، وهي مؤكدة على الرجال، وأوجبها بعض العلماء.', [H('hadith-bukhari', 'تفضل صلاة الفذ بسبع وعشرين درجة', '«صلاة الجماعة تفضل صلاة الفذ بسبع وعشرين درجة»', 'متفق عليه')], ('فضل الجماعة على صلاة الفرد:', ['عشر درجات', 'سبع وعشرون درجة'], 1))
w('salah', 'صلاة الجمعة', 'الجمعة واجبة على كل مسلم ذكر بالغ مقيم، ويحرم التهاون بها. ويستحب الغسل والتبكير والإنصات للخطبة.', [Q(62, 9), H('hadith-muslim', 'لينتهين أقوام عن ودعهم الجمعات', '«لينتهينّ أقوام عن ودعهم الجمعات أو ليختمنّ الله على قلوبهم»', 'رواه مسلم')], ('الكلام أثناء خطبة الجمعة:', ['جائز', 'منهي عنه'], 1))
w('salah', 'سجود السهو', 'إذا نسيت في صلاتك فزدت أو نقصت أو شككت، فاسجد سجدتين للسهو قبل السلام أو بعده. والشاك يبني على اليقين، وهو الأقل.', [H('hadith-muslim', 'فليطرح الشك وليبن على ما استيقن', '«إذا شك أحدكم في صلاته فلم يدرِ كم صلى، ثلاثاً أم أربعاً، فليطرح الشك وليبنِ على ما استيقن»', 'رواه مسلم')], ('شككت: صليت ثلاثاً أم أربعاً؟', ['تبني على الأكثر', 'تبني على الأقل وتسجد للسهو'], 1))
w('salah', 'صلاة المسافر', 'للمسافر أن يقصر الرباعية (الظهر والعصر والعشاء) إلى ركعتين، وله الجمع بين الظهر والعصر، وبين المغرب والعشاء. والمغرب والفجر لا تُقصران.', [Q(4, 101)], ('أي صلاة لا تُقصر؟', ['الظهر', 'العصر', 'المغرب'], 2))
w('salah', 'صلاة المريض', 'يصلي المريض قائماً، فإن لم يستطع فقاعداً، فإن لم يستطع فعلى جنبه. ولا تسقط الصلاة ما دام العقل حاضراً.', [H('hadith-bukhari', 'فإن لم تستطع فقاعدا', '«صلِّ قائماً، فإن لم تستطع فقاعداً، فإن لم تستطع فعلى جنب»', 'رواه البخاري')], ('المريض العاجز عن القيام:', ['يترك الصلاة', 'يصلي قاعداً'], 1))
w('salah', 'قضاء الصلاة الفائتة', 'من نام عن صلاة أو نسيها فليصلّها إذا ذكرها، ولا كفارة لها إلا ذلك.', [H('hadith-bukhari', 'من نسي صلاة فليصل إذا ذكرها', '«من نسي صلاة فليصلِّ إذا ذكرها، لا كفارة لها إلا ذلك»', 'متفق عليه')], ('نمت عن الفجر حتى طلعت الشمس:', ['تسقط عنك', 'تصليها إذا استيقظت'], 1))
w('salah', 'السنن الرواتب', 'اثنتا عشرة ركعة في اليوم من حافظ عليها بُني له بيت في الجنة: أربع قبل الظهر واثنتان بعدها، واثنتان بعد المغرب، واثنتان بعد العشاء، واثنتان قبل الفجر.', [H('hadith-muslim', 'ثنتي عشرة ركعة تطوعا', '«ما من عبد مسلم يصلي لله كل يوم ثنتي عشرة ركعة تطوعاً غير فريضة إلا بنى الله له بيتاً في الجنة»', 'رواه مسلم')], ('عدد الرواتب في اليوم:', ['عشر', 'اثنتا عشرة', 'ثماني'], 1))

# ===== الصيام =====
w('siyam', 'صيام رمضان', 'صوم رمضان ركن من أركان الإسلام، واجب على كل مسلم بالغ عاقل قادر مقيم. وهو إمساك عن المفطرات من طلوع الفجر إلى غروب الشمس بنية.', [Q(2, 183), Q(2, 187)], ('يبدأ الصوم من:', ['شروق الشمس', 'طلوع الفجر'], 1))
w('siyam', 'المفطرات', 'الأكل والشرب عمداً، والجماع، والقيء عمداً، وخروج دم الحيض والنفاس. ومن أكل أو شرب ناسياً فصومه صحيح.', [H('hadith-bukhari', 'فليتم صومه', '«من نسي وهو صائم فأكل أو شرب فليتمّ صومه، فإنما أطعمه الله وسقاه»', 'متفق عليه')], ('أكلت ناسياً وأنت صائم:', ['بطل صومك', 'صومك صحيح فأتمّه'], 1))
w('siyam', 'أصحاب الأعذار', 'المريض والمسافر يفطران ويقضيان. والحائض والنفساء يحرم عليهما الصوم وتقضيان. والكبير العاجز والمريض الذي لا يُرجى شفاؤه يطعمان عن كل يوم مسكيناً.', [Q(2, 184, 185)], ('الحائض في رمضان:', ['تصوم', 'تفطر وتقضي'], 1))
w('siyam', 'السحور وتعجيل الفطر', 'السحور بركة ولو بجرعة ماء، ومن السنة تأخيره، وتعجيل الفطر عند تيقن الغروب.', [H('hadith-bukhari', 'تسحروا فإن في السحور بركة', '«تسحّروا فإن في السحور بركة»', 'متفق عليه'), H('hadith-bukhari', 'لا يزال الناس بخير ما عجلوا الفطر', '«لا يزال الناس بخير ما عجّلوا الفطر»', 'متفق عليه')], ('من السنة:', ['تأخير الفطر', 'تعجيل الفطر'], 1))
w('siyam', 'حفظ الصيام من الإثم', 'الصيام ليس ترك الطعام فقط، بل ترك الكذب والغيبة والسباب. ومن لم يدع قول الزور فليس لله حاجة في أن يدع طعامه وشرابه.', [H('hadith-bukhari', 'من لم يدع قول الزور والعمل به', '«من لم يدع قول الزور والعمل به فليس لله حاجة في أن يدع طعامه وشرابه»', 'رواه البخاري')], ('الصيام الكامل:', ['ترك الطعام فقط', 'ترك الطعام والمعاصي'], 1))

# ===== الزكاة =====
w('zakah', 'فرض الزكاة', 'الزكاة ركن من أركان الإسلام، تجب في المال إذا بلغ النصاب وحال عليه الحول. وهي حق الفقير في مالك، تطهّره وتنميه.', [Q(9, 103), Q(2, 43)], ('شرطا وجوب الزكاة في النقود:', ['النصاب والحول', 'الغنى والسفر'], 0))
w('zakah', 'زكاة النقود والذهب', 'نصاب الذهب عشرون مثقالاً (نحو ٨٥ جراماً)، ونصاب الفضة مائتا درهم (نحو ٥٩٥ جراماً)، والواجب ربع العشر (٢٫٥٪) إذا حال الحول. والنقود الورقية تقدّر بأحدهما. استعمل حاسبة الزكاة في التطبيق.', [H('hadith-bukhari', 'ليس فيما دون خمس أواق صدقة', '«ليس فيما دون خمس أواقٍ صدقة»', 'متفق عليه')], ('مقدار زكاة النقود:', ['١٠٪', '٥٪', '٢٫٥٪'], 2))
w('zakah', 'مصارف الزكاة الثمانية', 'لا تُدفع الزكاة إلا لثمانية: الفقراء، والمساكين، والعاملين عليها، والمؤلفة قلوبهم، وفي الرقاب، والغارمين (المدينين)، وفي سبيل الله، وابن السبيل.', [Q(9, 60)], ('هل تُدفع الزكاة لبناء مسجد عند الجمهور؟', ['نعم', 'لا، ليس من الأصناف الثمانية'], 1))
w('zakah', 'زكاة الفطر', 'واجبة على كل مسلم صغير وكبير: صاع من طعام (نحو ٣ كيلو من قوت البلد) عن كل فرد، تُخرج قبل صلاة العيد، وتجوز قبله بيوم أو يومين.', [H('hadith-bukhari', 'فرض رسول الله صلى الله عليه وسلم زكاة الفطر صاعا من تمر', '«فرض رسول الله ﷺ زكاة الفطر صاعاً من تمر أو صاعاً من شعير على العبد والحر والذكر والأنثى والصغير والكبير من المسلمين، وأمر بها أن تؤدّى قبل خروج الناس إلى الصلاة»', 'متفق عليه')], ('وقت إخراج زكاة الفطر:', ['بعد العيد بأسبوع', 'قبل صلاة العيد'], 1))

# ===== الحج =====
w('hajj', 'فرض الحج', 'الحج واجب مرة في العمر على المسلم البالغ العاقل المستطيع بدنياً ومالياً. ومن استطاع فليبادر ولا يؤخّر.', [Q(3, 97)], ('الحج واجب:', ['كل سنة', 'مرة في العمر للمستطيع'], 1))
w('hajj', 'أركان العمرة', 'الإحرام (نية الدخول في النسك)، والطواف بالبيت سبعاً، والسعي بين الصفا والمروة سبعاً، ثم الحلق أو التقصير.', [Q(2, 158), Q(2, 196)], ('السعي يكون بين:', ['منى وعرفة', 'الصفا والمروة'], 1))
w('hajj', 'الحج عرفة', 'أعظم أركان الحج الوقوف بعرفة يوم التاسع من ذي الحجة، ومن فاته فاته الحج. ويوم عرفة لغير الحاج يُستحب صيامه، ويكفّر سنتين.', [H('hadith-muslim', 'صيام يوم عرفة أحتسب على الله', '«صيام يوم عرفة أحتسب على الله أن يكفّر السنة التي قبله والسنة التي بعده»', 'رواه مسلم')], ('أعظم أركان الحج:', ['رمي الجمرات', 'الوقوف بعرفة'], 1))

# ===== الحلال والحرام =====
w('haram', 'الربا', 'الربا من أكبر الكبائر: كل زيادة مشروطة في القرض، أو تأخير في بيع الذهب بالذهب والعملة بالعملة. ولعن النبي ﷺ آكله وموكله وكاتبه وشاهديه.', [Q(2, 275, 276), H('hadith-muslim', 'لعن رسول الله صلى الله عليه وسلم آكل الربا وموكله', '«لعن رسول الله ﷺ آكل الربا، وموكله، وكاتبه، وشاهديه، وقال: هم سواء»', 'رواه مسلم')], ('القرض بفائدة مشروطة:', ['جائز', 'ربا محرم'], 1))
w('haram', 'الغش في البيع والعمل', 'الغش في السلعة أو العمل أو الامتحان محرم، والصدق في البيع يبارك فيه.', [H('hadith-muslim', 'من غشنا فليس منا', '«من غشّنا فليس منا»', 'رواه مسلم')], ('إخفاء عيب السلعة عن المشتري:', ['ذكاء تجاري', 'غش محرم'], 1))
w('haram', 'الكذب', 'الكذب يهدي إلى الفجور، والصدق يهدي إلى البر. ولا يزال الرجل يصدق حتى يُكتب عند الله صدّيقاً.', [H('hadith-bukhari', 'إن الصدق يهدي إلى البر', '«إن الصدق يهدي إلى البر، وإن البر يهدي إلى الجنة... وإن الكذب يهدي إلى الفجور»', 'متفق عليه')], ('الكذب المازح:', ['لا بأس به', 'منهي عنه'], 1))
w('haram', 'الغيبة والنميمة', 'الغيبة: ذكرك أخاك بما يكره ولو كان فيه. والنميمة: نقل الكلام بين الناس للإفساد. وكلاهما كبيرة.', [Q(49, 12), H('hadith-muslim', 'أتدرون ما الغيبة', '«أتدرون ما الغيبة؟ ذكرك أخاك بما يكره» قيل: أفرأيت إن كان في أخي ما أقول؟ قال: «إن كان فيه ما تقول فقد اغتبته»', 'رواه مسلم')], ('ذكر عيب حقيقي في أخيك وهو غائب:', ['ليس غيبة لأنه صدق', 'غيبة محرمة'], 1))
w('haram', 'الخمر والمخدرات', 'كل مسكر خمر، وكل خمر حرام، قليله وكثيره، ويدخل فيه كل ما يذهب العقل من المخدرات.', [Q(5, 90), H('hadith-muslim', 'كل مسكر خمر وكل مسكر حرام', '«كل مسكر خمر، وكل مسكر حرام»', 'رواه مسلم')], ('القليل من المسكر:', ['جائز', 'حرام'], 1))
w('haram', 'حفظ الفرج والنظر', 'أمر الله بغض البصر وحفظ الفرج، وحرّم الزنا وما يقرّب إليه من الخلوة بالأجنبية والنظر المحرم.', [Q(24, 30, 31), Q(17, 32)], ('قوله ﴿ولا تقربوا الزنا﴾ يدل على:', ['تحريم الفعل فقط', 'تحريم الفعل وما يقرّب إليه'], 1))
w('haram', 'عقوق الوالدين', 'عقوق الوالدين من أكبر الكبائر بعد الشرك، حتى كلمة «أف» نهى الله عنها.', [Q(17, 23), H('hadith-bukhari', 'ألا أنبئكم بأكبر الكبائر', '«ألا أنبئكم بأكبر الكبائر؟» قالوا: بلى، قال: «الإشراك بالله، وعقوق الوالدين...»', 'متفق عليه')], ('أقل ما نهى الله عنه مع الوالدين:', ['الضرب', 'كلمة «أف»'], 1))
w('haram', 'الظلم وأكل الحقوق', 'الظلم ظلمات يوم القيامة: أخذ مال الغير، أو تأخير أجر العامل، أو أكل مال اليتيم، أو الاعتداء على الناس.', [H('hadith-bukhari', 'الظلم ظلمات يوم القيامة', '«الظلم ظلمات يوم القيامة»', 'متفق عليه'), Q(4, 10)], ('أكل مال اليتيم ظلماً:', ['ذنب صغير', 'من الكبائر'], 1))
w('haram', 'الرشوة', 'الرشوة: مال يُدفع لإبطال حق أو إحقاق باطل، وهي محرمة على الراشي والمرتشي.', [Q(2, 188)], ('دفع مال لتأخذ ما ليس لك:', ['شطارة', 'رشوة محرمة'], 1))

# ===== الأخلاق والآداب =====
w('akhlaq', 'بر الوالدين', 'برّهما: طاعتهما في المعروف، والإحسان إليهما، والدعاء لهما، وخفض الجناح لهما، خصوصاً عند الكبر.', [Q(17, 23, 24)], ('أحق الناس بحسن الصحبة:', ['الصديق', 'الأم'], 1))
w('akhlaq', 'صلة الرحم', 'صلة الأقارب بالزيارة والسؤال والهدية والمساعدة سبب لسعة الرزق وطول العمر، وقطعها كبيرة.', [H('hadith-bukhari', 'من سره أن يبسط له في رزقه', '«من سرّه أن يُبسط له في رزقه، أو يُنسأ له في أثره، فليصل رحمه»', 'متفق عليه')], ('صلة الرحم سبب في:', ['سعة الرزق', 'الفقر'], 0))
w('akhlaq', 'حق الجار', 'أحسن إلى جارك، ولا تؤذه بصوت أو رائحة أو نظر، وشاركه الطعام، وتفقّده.', [H('hadith-bukhari', 'لا يامن جاره', '«والله لا يؤمن، والله لا يؤمن، والله لا يؤمن» قيل: من يا رسول الله؟ قال: «الذي لا يأمن جاره بوائقه»', 'رواه البخاري')], ('إيذاء الجار:', ['أمر هيّن', 'ينافي كمال الإيمان'], 1))
w('akhlaq', 'حفظ اللسان', 'قل خيراً أو اصمت. فأكثر ما يُكبّ الناس في النار حصائد ألسنتهم.', [H('hadith-bukhari', 'من كان يؤمن بالله واليوم الآخر فليقل خيرا أو ليصمت', '«من كان يؤمن بالله واليوم الآخر فليقل خيراً أو ليصمت»', 'متفق عليه')], ('القاعدة في الكلام:', ['قل كل ما تعرف', 'قل خيراً أو اصمت'], 1))
w('akhlaq', 'إفشاء السلام', 'ابدأ بالسلام على من عرفت ومن لم تعرف، فهو سبب المحبة. وردّه واجب.', [Q(4, 86), H('hadith-muslim', 'أولا أدلكم على شيء إذا فعلتموه تحاببتم', '«أوَلا أدلّكم على شيء إذا فعلتموه تحاببتم؟ أفشوا السلام بينكم»', 'رواه مسلم')], ('ردّ السلام:', ['مستحب', 'واجب'], 1))
w('akhlaq', 'آداب الطعام', 'سمِّ الله، وكل بيمينك، ومما يليك، واحمد الله بعد الطعام. ولا تعب طعاماً قط.', [H('hadith-muslim', 'سم الله وكل بيمينك', '«يا غلام، سمِّ الله، وكل بيمينك، وكل مما يليك»', 'متفق عليه')], ('الأكل يكون:', ['باليمين', 'بأي يد'], 0))
w('akhlaq', 'التوبة باب مفتوح', 'مهما كان الذنب فباب التوبة مفتوح حتى تطلع الشمس من مغربها أو تبلغ الروح الحلقوم. شروطها: الإقلاع، والندم، والعزم على عدم العود، ورد الحقوق لأهلها.', [Q(39, 53)], ('هل يغفر الله الذنوب جميعاً لمن تاب؟', ['نعم', 'لا'], 0))
w('akhlaq', 'الأمانة', 'الأمانة في المال والعمل والسر والكلمة، وخيانتها من علامات النفاق.', [Q(4, 58), H('hadith-bukhari', 'آية المنافق ثلاث', '«آية المنافق ثلاث: إذا حدّث كذب، وإذا وعد أخلف، وإذا اؤتمن خان»', 'متفق عليه')], ('من علامات النفاق:', ['خيانة الأمانة', 'كثرة الصلاة'], 0))
w('akhlaq', 'الحياء', 'الحياء خير كله، وهو شعبة من الإيمان، يمنع صاحبه من القبيح.', [H('hadith-bukhari', 'الحياء لا يأتي إلا بخير', '«الحياء لا يأتي إلا بخير»', 'متفق عليه')], ('الحياء:', ['ضعف', 'شعبة من الإيمان'], 1))
w('akhlaq', 'الرفق', 'ما كان الرفق في شيء إلا زانه، ولا نُزع من شيء إلا شانه. ارفق بأهلك وأولادك والناس.', [H('hadith-muslim', 'إن الرفق لا يكون في شيء إلا زانه', '«إن الرفق لا يكون في شيء إلا زانه، ولا يُنزع من شيء إلا شانه»', 'رواه مسلم')], ('الرفق:', ['يزيّن كل شيء', 'ضعف في الشخصية'], 0))
